"use client";

import { useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import "./type-switcher.css";

export function TypeSwitcher({
  phrases,
  caption = "A change of perspective.",
}: {
  phrases: string[];
  caption?: string;
}) {
  const [index, setIndex] = useState(0);
  const reduce = useReducedMotion();
  if (!phrases.length) return null;
  return (
    <button
      className="forme-type-switcher"
      onClick={() => setIndex((index + 1) % phrases.length)}
      aria-label="Change the headline"
    >
      <span className="forme-type-top">
        Words with character.<span aria-hidden="true">↻</span>
      </span>
      <span className="forme-type-mask" aria-live="polite">
        <AnimatePresence mode="wait" initial={false}>
          <motion.span
            key={index}
            initial={{ y: reduce ? 0 : "110%", opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: reduce ? 0 : "-110%", opacity: 0 }}
            transition={{
              duration: reduce ? 0 : 0.45,
              ease: [0.22, 1, 0.36, 1],
            }}
          >
            {phrases[index]}
          </motion.span>
        </AnimatePresence>
      </span>
      <span className="forme-type-bottom">
        {caption}
        <span>
          {index + 1} / {phrases.length}
        </span>
      </span>
    </button>
  );
}

.forme-type-switcher {
  container-type: inline-size;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 25px;
  width: 100%;
  height: 100%;
  min-height: 270px;
  padding: 24px;
  border: 0;
  background: var(--forme-type-bg, #f0dcd3);
  color: var(--forme-type-color, #583d32);
  text-align: left;
  font: inherit;
  cursor: pointer;
}
.forme-type-top,
.forme-type-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  font-size: 10px;
  gap: 15px;
}
.forme-type-top > span {
  font-size: 22px;
}
.forme-type-mask {
  display: block;
  overflow: hidden;
  min-height: 130px;
  align-content: center;
  padding-block: 5px;
}
.forme-type-mask > span {
  display: block;
  max-width: 12ch;
  font-family: Georgia, serif;
  font-size: clamp(32px, 15cqi, 76px);
  line-height: 1.02;
  letter-spacing: -0.065em;
  overflow-wrap: anywhere;
}
.forme-type-bottom {
  font-size: 9px;
}
.forme-type-switcher:focus-visible {
  outline: 3px solid #617cf5;
  outline-offset: -5px;
}
